    Require(argc==2,"usage: mmv_native_shadow_bridge_tests <native-shadow fixture.pmx> | --guard-check");
    const bool guardOnly=std::wstring(argv[1])==L"--guard-check";
    const auto fixture=guardOnly?std::filesystem::path{}:std::filesystem::absolute(argv[1]);
    if(!guardOnly)Require(std::filesystem::is_regular_file(fixture),"existing owned PMX fixture");
    Require(!GetModuleHandleW(L"MMEffect.dll")&&!GetModuleHandleW(L"MMHack.dll"),"native MMV test excludes MME proxy");
    Require(MH_Initialize()==MH_OK,"initialize hidden process hooks");
    Hook(&CreateWindowExA,&CreateHiddenA,&originalCreateA);Hook(&CreateWindowExW,&CreateHiddenW,&originalCreateW);
    Hook(&ShowWindow,&Hide,&originalShow);Hook(&SetWindowPos,&Position,&originalPosition);Hook(&SetWindowPlacement,&Placement,&originalPlacement);
    Hook(&SetForegroundWindow,&Foreground,&originalForeground);
    Hook(&MessageBoxA,&UnexpectedA);Hook(&MessageBoxW,&UnexpectedW);
    Hook(&GetOpenFileNameA,&UnexpectedPickerA);Hook(&GetOpenFileNameW,&UnexpectedPickerW);
    Hook(&GetSaveFileNameA,&UnexpectedPickerA);Hook(&GetSaveFileNameW,&UnexpectedPickerW);
