    LoadModelFile(app,fixture.c_str(),false);Require(app->SelectedModel()&&mdl::Mdl(app->SelectedModel())->loadComplete,"load actual PMX geometry");
    app->PlaybackActive()=0;app->state.currentFrame=0;app->state.optflag[0]=1;app->EditMode()=ViewportEditMode::Camera;
    app->CameraReferenceMode()=CameraAttachmentReference::None;app->CameraParentModel()=-1;
    app->CameraPositionX()=0;app->CameraPositionY()=10;app->CameraPositionZ()=0;
    app->CameraPitch()=app->CameraYaw()=app->CameraRoll()=0;app->CameraDistance()=-45;app->CameraFov()=30;app->CameraPerspective()=0;
    app->ViewOffsetX()=app->ViewOffsetY()=0;app->GroundGridEnabled()=0;app->GroundShadowEnabled()=0;app->FpsOverlayEnabled()=0;
    app->state.selfShadowEnabled=1;app->AdaptiveShadowResolution()=false;app->ShadowDistance()=.01784f;
    Frame(app,0);const auto unshadowed=ReadRed(lastColor.Get());
